                techContainer.appendChild(grid);
            }
        }

        function updateFromInjectedText() {
            const dataContainer = document.getElementById('injected-data-container');
            if (!dataContainer) return;
            const rawText = dataContainer.textContent || "";
            const mainContentMatch = rawText.match(/<content>(.*?)<\/content>/s);
            const optionsMatch = rawText.match(/<option>(.*?)<\/option>/s);
            const mainContentEl = document.getElementById('main-content-text');
            if (mainContentMatch && mainContentEl) {
                mainContentEl.innerHTML = mainContentMatch[1].trim();
                formatSpecialText(mainContentEl);
            }
            const choicesContainer = document.getElementById('choices-container');
            if (optionsMatch && choicesContainer) {
                const optionLines = optionsMatch[1].trim().split('\n').filter(line => line.trim() !== '');
                choicesContainer.innerHTML = '';
                optionLines.forEach(line => {
                    const choiceText = line.trim();
                    if (!choiceText) return;
                    const choiceDiv = document.createElement('div');
                    choiceDiv.className = 'choice-item';
                    choiceDiv.innerHTML = choiceText;
                    choiceDiv.onclick = () => {
                        if (typeof triggerSlash === 'function') {
                            try { triggerSlash(`/send ${choiceText} | /trigger await=true`); } catch (e) { alert('指令发送失败: ' + choiceText); }
                        } else { alert('无法自动发送: ' + choiceText); }
                    };
                    choicesContainer.appendChild(choiceDiv);
                });
            } else if (choicesContainer) {
                choicesContainer.innerHTML = `<div class="choice-item">当前无选项，请自由行动...</div>`;
            }
        }

        function formatSpecialText(el) {
            const regex = /“([^”]+)”|"([^"]+)"|\*([^*]+)\*|【([^】]+)】/g;
            el.innerHTML = el.innerHTML.replace(regex, (match, dblQuote, dblQuote2, bold, bracket) => {
                if (dblQuote) return `<span class="dialog-text">“${dblQuote}”</span>`;
                if (dblQuote2) return `<span class="dialog-text">"${dblQuote2}"</span>`;
                if (bold) return `<span class="thought-text">**${bold}**</span>`;
                if (bracket) return `<strong style="color: var(--accent-gold);">【${bracket}】</strong>`;
                return match;
            });
        }

        function setupTabs() {
            const tabButtons = document.querySelectorAll('.tab-button');
            const tabContents = document.querySelectorAll('.tab-content');
            tabButtons.forEach(button => {
                button.onclick = () => {
                    tabButtons.forEach(btn => btn.classList.remove('active'));
                    tabContents.forEach(content => content.classList.remove('active'));
                    button.classList.add('active');
                    document.getElementById(button.dataset.tab).classList.add('active');
                };
            });
        }

        function setupPalette() {
            const btn = document.querySelector('.palette-button');
            const modal = document.querySelector('.palette-modal');
            const close = document.querySelector('.palette-close');
            const themeSel = document.getElementById('theme-select');
            const fontSel = document.getElementById('font-family-select');
            const sizeSel = document.getElementById('font-size-select');

            const applyTheme = (name) => {
                const theme = THEMES[name];
                if (theme) {
                    for (const [key, value] of Object.entries(theme)) {
                        document.documentElement.style.setProperty(key, value);
                    }
                    localStorage.setItem('sthm_theme', name);
                }
            };
            const applyFont = (name) => {
                const font = FONT_MAP[name];
                if (font) {
                    document.documentElement.style.setProperty('--font-main', font);
                    localStorage.setItem('sthm_font', name);
                }
            };
            const applySize = (size) => {
                document.documentElement.style.setProperty('--font-size-main', `${size}px`);
                localStorage.setItem('sthm_size', size);
            };
            btn.onclick = (e) => { e.stopPropagation(); modal.classList.toggle('show'); };
            close.onclick = () => modal.classList.remove('show');
            document.addEventListener('click', (e) => {
                if (modal && !modal.contains(e.target) && !btn.contains(e.target)) {
                    modal.classList.remove('show');
                }
            });
            themeSel.onchange = () => applyTheme(themeSel.value);
            fontSel.onchange = () => applyFont(fontSel.value);
            sizeSel.onchange = () => applySize(sizeSel.value);
            const savedTheme = localStorage.getItem('sthm_theme') || 'sheng_tang';
            const savedFont = localStorage.getItem('sthm_font') || 'yahei';
            const savedSize = localStorage.getItem('sthm_size') || '15';
            themeSel.value = savedTheme;
            fontSel.value = savedFont;
            sizeSel.value = savedSize;
            applyTheme(savedTheme);
            applyFont(savedFont);
            applySize(savedSize);
        }
        if (document.readyState === 'complete' || document.readyState === 'interactive') {
            initializeUI();
        } else {
            document.addEventListener('DOMContentLoaded', initializeUI);
        }
    })();
    </script>
</body>
</html>
